CREATE TABLE public.dre_feegow_linha (ordem int PRIMARY KEY, descricao text NOT NULL, condicao text NOT NULL);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dre_feegow_linha TO authenticated;
GRANT ALL ON public.dre_feegow_linha TO service_role;
ALTER TABLE public.dre_feegow_linha ENABLE ROW LEVEL SECURITY;
CREATE POLICY dre_feegow_linha_read ON public.dre_feegow_linha FOR SELECT TO authenticated USING (true);
CREATE POLICY dre_feegow_linha_admin ON public.dre_feegow_linha FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.dre_feegow_linha_item (id bigserial PRIMARY KEY, linha_descricao text NOT NULL, tipo_item text NOT NULL CHECK (tipo_item IN ('categoria','grupo')), nome text NOT NULL, categoria_id bigint, grupo_id bigint);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dre_feegow_linha_item TO authenticated;
GRANT ALL ON public.dre_feegow_linha_item TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.dre_feegow_linha_item_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.dre_feegow_linha_item_id_seq TO service_role;
ALTER TABLE public.dre_feegow_linha_item ENABLE ROW LEVEL SECURITY;
CREATE POLICY dre_feegow_item_read ON public.dre_feegow_linha_item FOR SELECT TO authenticated USING (true);
CREATE POLICY dre_feegow_item_admin ON public.dre_feegow_linha_item FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.dre_feegow_referencia (ordem int, linha text, mes int, valor numeric(14,2), ano int DEFAULT 2026);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dre_feegow_referencia TO authenticated;
GRANT ALL ON public.dre_feegow_referencia TO service_role;
ALTER TABLE public.dre_feegow_referencia ENABLE ROW LEVEL SECURITY;
CREATE POLICY dre_feegow_referencia_read ON public.dre_feegow_referencia FOR SELECT TO authenticated USING (true);
CREATE POLICY dre_feegow_referencia_admin ON public.dre_feegow_referencia FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.dre_feegow_normalizar_nome(s text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path = public AS $$ SELECT regexp_replace(public.dre_normalizar(s), '[[:space:]]+', ' ', 'g') $$;
GRANT EXECUTE ON FUNCTION public.dre_feegow_normalizar_nome(text) TO authenticated, service_role;